changeSet.sql:
CREATE TABLE IF NOT EXISTS app.part_partattribute ( part_attribute_id BIGSERIAL PRIMARY KEY, part_id BIGINT NOT NULL, attribute_id BIGINT NOT NULL, attribute_value VARCHAR(255) NOT NULL, delete_flag INTEGER DEFAULT 0, created_by BIGINT, created_date_time TIMESTAMPTZ(6), updated_by BIGINT, updated_date_time TIMESTAMPTZ(6),
CONSTRAINT fk_part_attribute_id_part FOREIGN KEY (part_id) REFERENCES app.part(part_id) ON DELETE CASCADE, CONSTRAINT fk_part_attribute_id_part_attribute FOREIGN KEY (attribute_id) REFERENCES app.part_attribute(attribute_id) ON DELETE CASCADE,
CONSTRAINT uq_part_partattribute UNIQUE (part_id, attribute_id) );
